<?php require 'db.php';$s=$pdo->prepare("SELECT sc.id,sub.code subject_code,sub.name subject_name,sc.day_of_week,TO_CHAR(sc.start_time,'HH24:MI') start_time,TO_CHAR(sc.end_time,'HH24:MI') end_time,r.room_name,r.building,COALESCE(f.first_name||' '||f.last_name,'TBA') faculty_name FROM schedules sc JOIN subjects sub ON sub.id=sc.subject_id JOIN rooms r ON r.id=sc.room_id LEFT JOIN faculty f ON f.id=sc.faculty_id JOIN sections sec ON sec.id=sc.section_id JOIN users u ON u.section_id=sec.id WHERE u.id=:i ORDER BY sc.start_time");$s->execute([':i'=>(int)($_GET['user_id']??0)]);echo json_encode(['success'=>true,'data'=>$s->fetchAll(PDO::FETCH_ASSOC)]);?>